export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

export class ProjectService {
    private readonly projects: Map<string, Project> = new Map();

    create(name: string, description: string): Project {
        const id = crypto.randomUUID();
        const project: Project = { id, name, description, memberIds: [] };
        this.projects.set(id, project);
        return project;
    }

    getById(id: string): Project | undefined {
        return this.projects.get(id);
    }

    getAll(): Project[] {
        return Array.from(this.projects.values());
    }

    update(id: string, name: string, description: string): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            project.name = name;
            project.description = description;
            return project;
        }
        return undefined;
    }

    delete(id: string): boolean {
        return this.projects.delete(id);
    }

    addMember(id: string, memberId: string): Project | undefined {
        const project = this.projects.get(id);
        if (project && !project.memberIds.includes(memberId)) {
            project.memberIds.push(memberId);
            return project;
        }
        return undefined;
    }

    removeMember(id: string, memberId: string): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            const index = project.memberIds.indexOf(memberId);
            if (index > -1) {
                project.memberIds.splice(index, 1);
                return project;
            }
        }
        return undefined;
    }
}

import crypto from "crypto";
import { EventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

const statusOrder: TaskStatus[] = ["todo", "in-progress", "done"];

export class TaskService {
    private readonly tasks: Map<string, Task> = new Map();

    constructor(private readonly eventBus: EventBus) {}

    create(title: string, description: string, projectId: string): Task {
        const id = crypto.randomUUID();
        const task: Task = { id, title, description, status: "todo", assigneeId: null, projectId };
        this.tasks.set(id, task);
        return task;
    }

    getById(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    getByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    update(id: string, title: string, description: string): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            task.title = title;
            task.description = description;
            return task;
        }
        return undefined;
    }

    delete(id: string): boolean {
        return this.tasks.delete(id);
    }

    assign(id: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            task.assigneeId = assigneeId;
            this.eventBus.publish("task.assigned", { 
                taskId: task.id, 
                taskTitle: task.title, 
                assigneeId: task.assigneeId 
            });
            return task;
        }
        return undefined;
    }

    changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;
        const oldIndex = statusOrder.indexOf(oldStatus);
        const newIndex = statusOrder.indexOf(newStatus);

        if (newIndex > oldIndex) {
            task.status = newStatus;
            if (task.assigneeId) {
                this.eventBus.publish("task.statusChanged", {
                    taskId: task.id,
                    taskTitle: task.title,
                    assigneeId: task.assigneeId,
                    oldStatus,
                    newStatus,
                });
            }
            return task;
        }

        return undefined; // Invalid status transition
    }
}

